process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs5', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs5 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS5'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP uxs5 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP uxs5 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd2=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.on('dialog',async d=>{ out.dialogas=(d.message()||'').slice(0,120); await d.accept(); });

  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  /* nuscrollinam sarasa zemyn — kad matytusi, ar kortele atsidaro nuo virsaus */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=prekyboje&q=lamb&per=50`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  await page.evaluate(()=>window.scrollTo(0, 900));
  await pause(400);
  const eiles=await page.$$('.pskat-t tbody tr[data-id] a.atv');
  out.eiluciu=eiles.length;
  if(eiles.length>2){
    await eiles[2].click(); await pause(3500);
    out.langas_scrollY=await page.evaluate(()=>window.scrollY);
    out.kort_scrollTop=await page.evaluate(()=>{ const k=document.getElementById('pskat-kort'); return k?k.scrollTop:null; });
    out.pirmas_matomas=await page.evaluate(()=>{
      const h=document.querySelector('.kort-pav h2'); if(!h) return null;
      const r=h.getBoundingClientRect(); return {tekstas:h.textContent.trim().slice(0,50), top:Math.round(r.top), matomas:r.top>0&&r.top<400};
    });
    let png=await page.screenshot(); out.s_virsus=await putRaw('screenshots/uxs5_nuo_virsaus.png', png.toString('base64'),'uxs5 virsus');

    /* ATRIBUTAI: atidarom pirma atributa, keiciam reiksme, irasom */
    out.atr_blokai=await page.evaluate(()=>Array.prototype.map.call(document.querySelectorAll('.kort-atr'),
      x=>({tax:x.dataset.tax, dabar:x.querySelector('.kort-atr-rodo').textContent.trim(), daug:x.dataset.daug})));
    const keisti=await page.$('.kort-atr[data-daug="0"] .kort-atr-keisti');
    if(keisti){
      await keisti.click(); await pause(600);
      out.atr_lauk_atviras=await page.evaluate(()=>{
        const l=document.querySelector('.kort-atr[data-daug="0"] .kort-atr-lauk'); return l?!l.hidden:null; });
      out.atr_pasirinkimu=await page.evaluate(()=>{
        const s=document.querySelector('.kort-atr[data-daug="0"] .kort-atr-sel'); return s?s.options.length:0; });
      /* pasirenkam pirma NE-tuscia varianta ir irasom */
      const pries=await page.evaluate(()=>{
        const blk=document.querySelector('.kort-atr[data-daug="0"]');
        return {tax:blk.dataset.tax, rodo:blk.querySelector('.kort-atr-rodo').textContent.trim(),
                pasirinkta:blk.querySelector('.kort-atr-sel').value};
      });
      out.atr_pries=pries;
      await page.evaluate(()=>{
        const s=document.querySelector('.kort-atr[data-daug="0"] .kort-atr-sel');
        for(const o of s.options){ if(o.value && o.value!==s.value){ s.value=o.value; break; } }
      });
      await page.click('.kort-atr[data-daug="0"] .kort-atr-irasyti');
      await pause(2500);
      out.atr_po=await page.evaluate(()=>{
        const blk=document.querySelector('.kort-atr[data-daug="0"]');
        return {rodo:blk.querySelector('.kort-atr-rodo').textContent.trim(),
                stat:blk.querySelector('.kort-atr-stat').textContent.trim(),
                lauk_uzdarytas:blk.querySelector('.kort-atr-lauk').hidden};
      });
      png=await page.screenshot(); out.s_atr=await putRaw('screenshots/uxs5_atributai.png', png.toString('base64'),'uxs5 atr');
      /* grazinam pradine reiksme */
      await page.evaluate((p)=>{
        const blk=document.querySelector('.kort-atr[data-daug="0"]');
        blk.querySelector('.kort-atr-keisti').click();
        const s=blk.querySelector('.kort-atr-sel'); s.value=p.pasirinkta;
        blk.querySelector('.kort-atr-irasyti').click();
      }, pries);
      await pause(2500);
      out.atr_atstatyta=await page.evaluate(()=>document.querySelector('.kort-atr[data-daug="0"] .kort-atr-rodo').textContent.trim());
    } else { out.atr_lauk_atviras='keisti mygtukas nerastas'; }

    /* NUOTRAUKOS skirtukas */
    await page.evaluate(()=>{ const b=document.querySelector('.kort-tabs button[data-t=fot]'); if(b) b.click(); });
    await pause(1200);
    out.foto=await page.evaluate(()=>{
      const p=document.querySelector('.kort-pane[data-p=fot]'); if(!p) return null;
      return {mygtukai:Array.prototype.map.call(p.querySelectorAll('.kort-foto-myg button'),b=>b.textContent.trim()),
              galerijos_el:p.querySelectorAll('.kg-el').length,
              alt_laukas:!!p.querySelector('.kort-alt input')};
    });
    png=await page.screenshot(); out.s_foto=await putRaw('screenshots/uxs5_nuotraukos.png', png.toString('base64'),'uxs5 foto');
  }
  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs5.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs5.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,700)}); });
